Then('{string} contains a main list section', function (filename) {
  const html = fs.readFileSync(path.join(ROOT, filename), 'utf-8');
  if (!html.includes('class="todo-list"') && !html.includes("class='todo-list'")) {
    throw new Error('No todo list section found in ' + filename);
  }
});

Then('{string} contains a footer with controls', function (filename) {
  const html = fs.readFileSync(path.join(ROOT, filename), 'utf-8');
  if (!html.includes('class="footer"') && !html.includes("class='footer'")) {
    throw new Error('No footer section found in ' + filename);
  }
  if (!html.includes('class="clear-completed"') && !html.includes("class='clear-completed'")) {
    throw new Error('No clear-completed button found in footer');
  }
});

Then('{string} loads {string} via a script tag', function (filename, scriptSrc) {
  const html = fs.readFileSync(path.join(ROOT, filename), 'utf-8');
  const expected = 'src="' + scriptSrc + '"';
  if (!html.includes(expected)) throw new Error('Script src "' + scriptSrc + '" not found in ' + filename);
});

const { World } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const TEMPLATE_PATH = path.resolve(__dirname, '../../assets/app-template.index.html');

class TodoWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
  }

  renderFresh() {
    const html = fs.readFileSync(TEMPLATE_PATH, 'utf-8');
    const window = new Window({ url: 'http://localhost/' });
    const document = window.document;

    document.write(html);
    document.close();

    // Reset localStorage
    window.localStorage.clear();

    this.window = window;
    this.document = document;

    return { window, document };
  }

  evaluateAppCode(code) {
    if (!this.window) throw new Error('Window not initialized');
    try {
      const fn = new this.window.Function('window', 'document', code);
      fn(this.window, this.document);
    } catch (e) {
      // App code may not exist yet, that's fine
    }
  }

  // Get the todo list items
  getTodoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  getTodoItem(title) {
    return this.getTodoItems().find(li => {
      const label = li.querySelector('label');
      return label && label.textContent.trim() === title;
    });
  }

  getNewTodoInput() {
    return this.document.querySelector('.new-todo');
  }

  getToggleAll() {
    return this.document.querySelector('.toggle-all');
  }

  getClearCompleted() {
    return this.document.querySelector('.clear-completed');
  }

  getTodoCount() {
    return this.document.querySelector('.todo-count');
  }

  getMainSection() {
    return this.document.querySelector('.main');
  }

  getFooterSection() {
    return this.document.querySelector('.footer');
  }

  getFilterLink(name) {
    const filters = this.document.querySelectorAll('.filters a');
    return Array.from(filters).find(a => a.textContent.trim() === name);
  }
}

module.exports = { TodoWorld };

(function (window, document) {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  // Guard against double initialization
  if (window.__todoAppInitialized) return;
  window.__todoAppInitialized = true;

  var todoApp = document.querySelector('.todoapp');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var newTodo = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var toggleAll = document.querySelector('.toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var filters = document.querySelector('.filters');

  function loadTodos() {
    try {
      var data = window.localStorage.getItem(STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos(todos) {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function getId() {
    return Date.now().toString() + Math.random().toString(36).slice(2, 8);
  }

  function getFilteredTodos(todos, filter) {
    if (filter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (filter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function getActiveCount(todos) {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  function getCompletedCount(todos) {
    return todos.filter(function (t) { return t.completed; }).length;
  }

  function render() {
    var todos = loadTodos();
    var filter = window.__todoFilter || 'all';
    var filtered = getFilteredTodos(todos, filter);
    var html = '';
    filtered.forEach(function (todo) {
      var liClass = '';
      if (todo.completed) liClass += 'completed';
      html += '<li' + (liClass ? ' class="' + liClass + '"' : '') + '>';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>';
      html += '<label>' + escapeHtml(todo.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';
      html += '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      html += '</li>';
    });
    todoList.innerHTML = html;

    // Attach edit handlers to each item
    var allLi = todoList.children;
    for (var i = 0; i < allLi.length; i++) {
      attachEditHandlers(allLi[i]);
    }

    var hasTodos = todos.length > 0;
    main.style.display = hasTodos ? '' : 'none';
    footer.style.display = hasTodos ? '' : 'none';

    var allCompleted = hasTodos && getActiveCount(todos) === 0;
    toggleAll.checked = allCompleted;

    var activeCount = getActiveCount(todos);
    var word = activeCount === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

    var completedCount = getCompletedCount(todos);
    clearCompleted.style.display = completedCount > 0 ? '' : 'none';

    var filterLinks = filters.querySelectorAll('a');
    Array.prototype.forEach.call(filterLinks, function (a) {
      var href = a.getAttribute('href');
      a.classList.toggle('selected',
        (href === '#/' && filter === 'all') ||
        (href === '#/active' && filter === 'active') ||
        (href === '#/completed' && filter === 'completed'));
    });
  }

  function escapeHtml(text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;
    var todos = loadTodos();
    todos.push({ id: getId(), title: trimmed, completed: false });
    saveTodos(todos);
    render();
  }

  function removeTodo(id) {
    var todos = loadTodos().filter(function (t) { return t.id !== id; });
    saveTodos(todos);
    render();
  }

  function toggleTodo(id) {
    var todos = loadTodos();
    todos.forEach(function (t) { if (t.id === id) t.completed = !t.completed; });
    saveTodos(todos);
    render();
  }

  function toggleAllTodos() {
    var todos = loadTodos();
    var allCompleted = todos.length > 0 && getActiveCount(todos) === 0;
    todos.forEach(function (t) { t.completed = !allCompleted; });
    saveTodos(todos);
    render();
  }

  function clearCompletedTodos() {
    var todos = loadTodos().filter(function (t) { return !t.completed; });
    saveTodos(todos);
    render();
  }

  function saveEdit(id, title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      removeTodo(id);
      return;
    }
    var todos = loadTodos();
    todos.forEach(function (t) { if (t.id === t.id) { if (t.id === id) t.title = trimmed; } });
    saveTodos(todos);
    render();
  }

  function setFilter(filter) {
    window.__todoFilter = filter;
    try { window.localStorage.setItem(STORAGE_KEY + '-filter', filter); } catch (e) {}
    render();
  }

  // Event delegation for todo list
